void ubifs_dump_node(const struct ubifs_info *c, const void *node)
{
    extern void dump_ch(const struct ubifs_ch *ch);
    extern const char *dbg_snprintf_key(const struct ubifs_info *c,
                                       const union ubifs_key *key,
                                       char *buffer, int len);
    extern const char *get_key_hash(int hash);
    extern const char *get_key_fmt(int fmt);
    extern int print_hex_dump(const char *prefix, int prefix_type,
                              int rowsize, int groupsize, const void *buf,
                              size_t len, bool ascii);

    const struct ubifs_ch *ch = node;
    char key_buf[DBG_KEY_BUF_LEN];
    union ubifs_key key;

    if (ch->magic != UBIFS_NODE_MAGIC) {
        printf("Not a node, first %zu bytes:", sizeof(*ch));
        print_hex_dump("", DUMP_PREFIX_OFFSET, 32, 1, node, sizeof(*ch), true);
        return;
    }

    dump_ch(ch);

    switch (ch->node_type) {
    case UBIFS_INO_NODE: {
        const struct ubifs_ino_node *ino = node;

        key.u32[0] = ((const uint32_t *)ino->key)[0];
        key.u32[1] = ((const uint32_t *)ino->key)[1];
        printf("\tkey            %s\n",
               dbg_snprintf_key(c, &key, key_buf, sizeof(key_buf)));
        printf("\tcreat_sqnum    %llu\n", (unsigned long long)ino->creat_sqnum);
        printf("\tsize           %llu\n", (unsigned long long)ino->size);
        printf("\tnlink          %u\n", ino->nlink);
        printf("\tatime          %lld.%u\n",
               (long long)ino->atime_sec, ino->atime_nsec);
        printf("\tmtime          %lld.%u\n",
               (long long)ino->mtime_sec, ino->mtime_nsec);
        printf("\tctime          %lld.%u\n",
               (long long)ino->ctime_sec, ino->ctime_nsec);
        printf("\tuid            %u\n", ino->uid);
        printf("\tgid            %u\n", ino->gid);
        printf("\tmode           %u\n", ino->mode);
        printf("\tflags          %#x\n", ino->flags);
        printf("\txattr_cnt      %u\n", ino->xattr_cnt);
        printf("\txattr_size     %u\n", ino->xattr_size);
        printf("\txattr_names    %u\n", ino->xattr_names);
        printf("\tcompr_type     %#x\n", (unsigned int)ino->compr_type);
        printf("\tdata len       %u\n", ino->data_len);
        break;
    }
    case UBIFS_DATA_NODE: {
        const struct ubifs_data_node *dn = node;
        int dlen = (int)(dn->ch.len - (uint32_t)sizeof(*dn));

        key.u32[0] = ((const uint32_t *)dn->key)[0];
        key.u32[1] = ((const uint32_t *)dn->key)[1];
        printf("\tkey            %s\n",
               dbg_snprintf_key(c, &key, key_buf, sizeof(key_buf)));
        printf("\tsize           %u\n", dn->size);
        printf("\tcompr_typ      %d\n", dn->compr_type);
        printf("\tdata size      %d\n", dlen);
        printf("\tdata:\n");
        print_hex_dump("\t", DUMP_PREFIX_OFFSET, 32, 1, dn->data, dlen, false);
        break;
    }
    case UBIFS_DENT_NODE:
    case UBIFS_XENT_NODE: {
        const struct ubifs_dent_node *dent = node;
        int nlen = dent->nlen;

        key.u32[0] = ((const uint32_t *)dent->key)[0];
        key.u32[1] = ((const uint32_t *)dent->key)[1];
        printf("\tkey            %s\n",
               dbg_snprintf_key(c, &key, key_buf, sizeof(key_buf)));
        printf("\tinum           %llu\n", (unsigned long long)dent->inum);
        printf("\ttype           %d\n", dent->type);
        printf("\tnlen           %d\n", nlen);
        printf("\tname           ");
        if (nlen > UBIFS_MAX_NLEN) {
            printf("(bad name length, not printing, bad or corrupted node)");
        } else {
            for (int i = 0; i < nlen && dent->name[i]; ++i)
                printf("%c", dent->name[i]);
        }
        printf("\n");
        break;
    }
    case UBIFS_TRUN_NODE: {
        const struct ubifs_trun_node *trun = node;

        printf("\tinum           %u\n", trun->inum);
        printf("\told_size       %llu\n", (unsigned long long)trun->old_size);
        printf("\tnew_size       %llu\n", (unsigned long long)trun->new_size);
        break;
    }
    case UBIFS_PAD_NODE: {
        const struct ubifs_pad_node *pad = node;

        printf("\tpad_len        %u\n", pad->pad_len);
        break;
    }
    case UBIFS_SB_NODE: {
        const struct ubifs_sb_node *sb = node;
        uint32_t flags = sb->flags;

        printf("\tkey_hash       %d (%s)\n", sb->key_hash,
               get_key_hash(sb->key_hash));
        printf("\tkey_fmt        %d (%s)\n", sb->key_fmt,
               get_key_fmt(sb->key_fmt));
        printf("\tflags          %#x\n", flags);
        printf("\tbig_lpt        %u\n", (unsigned int)!!(flags & UBIFS_FLG_BIGLPT));
        printf("\tspace_fixup    %u\n",
               (unsigned int)!!(flags & UBIFS_FLG_SPACE_FIXUP));
        printf("\tmin_io_size    %u\n", sb->min_io_size);
        printf("\tleb_size       %u\n", sb->leb_size);
        printf("\tleb_cnt        %u\n", sb->leb_cnt);
        printf("\tmax_leb_cnt    %u\n", sb->max_leb_cnt);
        printf("\tmax_bud_bytes  %llu\n", (unsigned long long)sb->max_bud_bytes);
        printf("\tlog_lebs       %u\n", sb->log_lebs);
        printf("\tlpt_lebs       %u\n", sb->lpt_lebs);
        printf("\torph_lebs      %u\n", sb->orph_lebs);
        printf("\tjhead_cnt      %u\n", sb->jhead_cnt);
        printf("\tfanout         %u\n", sb->fanout);
        printf("\tlsave_cnt      %u\n", sb->lsave_cnt);
        printf("\tdefault_compr  %u\n", (unsigned int)sb->default_compr);
        printf("\trp_size        %llu\n", (unsigned long long)sb->rp_size);
        printf("\trp_uid         %u\n", sb->rp_uid);
        printf("\trp_gid         %u\n", sb->rp_gid);
        printf("\tfmt_version    %u\n", sb->fmt_version);
        printf("\ttime_gran      %u\n", sb->time_gran);
        printf("\tUUID           %pUB\n", (const void *)sb->uuid);
        break;
    }
    case UBIFS_MST_NODE: {
        const struct ubifs_mst_node *mst = node;

        printf("\thighest_inum   %llu\n", (unsigned long long)mst->highest_inum);
        printf("\tcommit number  %llu\n", (unsigned long long)mst->cmt_no);
        printf("\tflags          %#x\n", mst->flags);
        printf("\tlog_lnum       %u\n", mst->log_lnum);
        printf("\troot_lnum      %u\n", mst->root_lnum);
        printf("\troot_offs      %u\n", mst->root_offs);
        printf("\troot_len       %u\n", mst->root_len);
        printf("\tgc_lnum        %u\n", mst->gc_lnum);
        printf("\tihead_lnum     %u\n", mst->ihead_lnum);
        printf("\tihead_offs     %u\n", mst->ihead_offs);
        printf("\tindex_size     %llu\n", (unsigned long long)mst->index_size);
        printf("\tlpt_lnum       %u\n", mst->lpt_lnum);
        printf("\tlpt_offs       %u\n", mst->lpt_offs);
        printf("\tnhead_lnum     %u\n", mst->nhead_lnum);
        printf("\tnhead_offs     %u\n", mst->nhead_offs);
        printf("\tltab_lnum      %u\n", mst->ltab_lnum);
        printf("\tltab_offs      %u\n", mst->ltab_offs);
        printf("\tlsave_lnum     %u\n", mst->lsave_lnum);
        printf("\tlsave_offs     %u\n", mst->lsave_offs);
        printf("\tlscan_lnum     %u\n", mst->lscan_lnum);
        printf("\tleb_cnt        %u\n", mst->leb_cnt);
        printf("\tempty_lebs     %u\n", mst->empty_lebs);
        printf("\tidx_lebs       %u\n", mst->idx_lebs);
        printf("\ttotal_free     %llu\n", (unsigned long long)mst->total_free);
        printf("\ttotal_dirty    %llu\n", (unsigned long long)mst->total_dirty);
        printf("\ttotal_used     %llu\n", (unsigned long long)mst->total_used);
        printf("\ttotal_dead     %llu\n", (unsigned long long)mst->total_dead);
        printf("\ttotal_dark     %llu\n", (unsigned long long)mst->total_dark);
        break;
    }
    case UBIFS_REF_NODE: {
        const struct ubifs_ref_node *ref = node;

        printf("\tlnum           %u\n", ref->lnum);
        printf("\toffs           %u\n", ref->offs);
        printf("\tjhead          %u\n", ref->jhead);
        break;
    }
    case UBIFS_IDX_NODE: {
        const struct ubifs_idx_node *idx = node;
        int child_cnt = idx->child_cnt;

        printf("\tchild_cnt      %d\n", child_cnt);
        printf("\tlevel          %d\n", idx->level);
        printf("\tBranches:\n");
        for (int i = 0; i < child_cnt && i < c->fanout - 1; ++i) {
            const struct ubifs_branch *branch =
                (const struct ubifs_branch *)(idx->branches +
                    i * (sizeof(struct ubifs_branch) + c->key_len));

            key.u32[0] = ((const uint32_t *)branch->key)[0];
            key.u32[1] = ((const uint32_t *)branch->key)[1];
            printf("\t%d: LEB %d:%d len %d key %s\n", i,
                   (int)branch->lnum, (int)branch->offs, (int)branch->len,
                   dbg_snprintf_key(c, &key, key_buf, sizeof(key_buf)));
        }
        break;
    }
    case UBIFS_CS_NODE:
        break;
    case UBIFS_ORPH_NODE: {
        const struct ubifs_orph_node *orph = node;
        int n;

        printf("\tcommit number  %llu\n",
               (unsigned long long)(orph->cmt_no & UINT64_C(0x7fffffffffffffff)));
        printf("\tlast node flag %llu\n",
               (unsigned long long)(orph->cmt_no >> 63));
        n = (orph->ch.len - (uint32_t)sizeof(*orph)) / sizeof(orph->inos[0]);
        printf("\t%d orphan inode numbers:\n", n);
        for (int i = 0; i < n; ++i)
            printf("\t  ino %llu\n", (unsigned long long)orph->inos[i]);
        break;
    }
    default:
        printf("node type %d was not recognized\n", ch->node_type);
        break;
    }
}

