int main (int argc, char **argv)
{
#ifdef ACCT_TOOLS_SETUID
#ifdef USE_PAM
	pam_handle_t *pamh = NULL;
	int retval;
#endif				/* USE_PAM */
#endif				/* ACCT_TOOLS_SETUID */

	/*
	 * Get my name so that I can use it to report errors.
	 */
	Prog = Basename (argv[0]);
	log_set_progname(Prog);
	log_set_logfd(stderr);

	(void) setlocale (LC_ALL, "");
	(void) bindtextdomain (PACKAGE, LOCALEDIR);
	(void) textdomain (PACKAGE);

	process_root_flag ("-R", argc, argv);
	prefix = process_prefix_flag ("-P", argc, argv);

	OPENLOG ("usermod");
#ifdef WITH_AUDIT
	audit_help_open ();
#endif

	sys_ngroups = sysconf (_SC_NGROUPS_MAX);
	user_groups = (char **) malloc (sizeof (char *) * (1 + sys_ngroups));
	user_groups[0] = (char *) 0;

	is_shadow_pwd = spw_file_present ();
#ifdef SHADOWGRP
	is_shadow_grp = sgr_file_present ();
#endif
#ifdef ENABLE_SUBIDS
	is_sub_uid = sub_uid_file_present ();
	is_sub_gid = sub_gid_file_present ();
#endif				/* ENABLE_SUBIDS */

	process_flags (argc, argv);

	/*
	 * The home directory, the username and the user's UID should not
	 * be changed while the user is logged in.
	 * Note: no need to check if a prefix is specified...
	 */
	if ( (prefix[0] == '\0') &&  (uflg || lflg || dflg
#ifdef ENABLE_SUBIDS
	        || Vflg || Wflg
#endif				/* ENABLE_SUBIDS */
	       )
	    && (user_busy (user_name, user_id) != 0)) {
		exit (E_USER_BUSY);
	}

#ifdef ACCT_TOOLS_SETUID
#ifdef USE_PAM
	{
		struct passwd *pampw;
		pampw = getpwuid (getuid ()); /* local, no need for xgetpwuid */
		if (pampw == NULL) {
			fprintf (stderr,
			         _("%s: Cannot determine your user name.\n"),
			         Prog);
			exit (1);
		}

		retval = pam_start ("usermod", pampw->pw_name, &conv, &pamh);
	}

	if (PAM_SUCCESS == retval) {
		retval = pam_authenticate (pamh, 0);
	}

	if (PAM_SUCCESS == retval) {
		retval = pam_acct_mgmt (pamh, 0);
	}

	if (PAM_SUCCESS != retval) {
		fprintf (stderr, _("%s: PAM: %s\n"),
		         Prog, pam_strerror (pamh, retval));
		SYSLOG((LOG_ERR, "%s", pam_strerror (pamh, retval)));
		if (NULL != pamh) {
			(void) pam_end (pamh, retval);
		}
		exit (1);
	}
	(void) pam_end (pamh, retval);
#endif				/* USE_PAM */
#endif				/* ACCT_TOOLS_SETUID */

#ifdef WITH_TCB
	if (shadowtcb_set_user (user_name) == SHADOWTCB_FAILURE) {
		exit (E_PW_UPDATE);
	}
#endif

	/*
	 * Do the hard stuff - open the files, change the user entries,
	 * change the home directory, then close and update the files.
	 */
	open_files ();
	if (   cflg || dflg || eflg || fflg || gflg || Lflg || lflg || pflg
	    || sflg || uflg || Uflg) {
		usr_update ();
	}
	if (Gflg || lflg) {
		grp_update ();
	}
#ifdef ENABLE_SUBIDS
	if (Vflg) {
		struct ulong_range_list_entry *ptr;
		for (ptr = del_sub_uids; ptr != NULL; ptr = ptr->next) {
			unsigned long count = ptr->range.last - ptr->range.first + 1;
			if (sub_uid_remove(user_name, ptr->range.first, count) == 0) {
				fprintf (stderr,
					_("%s: failed to remove uid range %lu-%lu from '%s'\n"),
					Prog, ptr->range.first, ptr->range.last,
					sub_uid_dbname ());
				fail_exit (E_SUB_UID_UPDATE);
			}
		}
	}
	if (vflg) {
		struct ulong_range_list_entry *ptr;
		for (ptr = add_sub_uids; ptr != NULL; ptr = ptr->next) {
			unsigned long count = ptr->range.last - ptr->range.first + 1;
			if (sub_uid_add(user_name, ptr->range.first, count) == 0) {
				fprintf (stderr,
					_("%s: failed to add uid range %lu-%lu to '%s'\n"),
					Prog, ptr->range.first, ptr->range.last,
					sub_uid_dbname ());
				fail_exit (E_SUB_UID_UPDATE);
			}
		}
	}
	if (Wflg) {
		struct ulong_range_list_entry *ptr;
		for (ptr = del_sub_gids; ptr != NULL; ptr = ptr->next) {
			unsigned long count = ptr->range.last - ptr->range.first + 1;
			if (sub_gid_remove(user_name, ptr->range.first, count) == 0) {
				fprintf (stderr,
					_("%s: failed to remove gid range %lu-%lu from '%s'\n"),
					Prog, ptr->range.first, ptr->range.last,
					sub_gid_dbname ());
				fail_exit (E_SUB_GID_UPDATE);
			}
		}
	}
	if (wflg) {
		struct ulong_range_list_entry *ptr;
		for (ptr = add_sub_gids; ptr != NULL; ptr = ptr->next) {
			unsigned long count = ptr->range.last - ptr->range.first + 1;
			if (sub_gid_add(user_name, ptr->range.first, count) == 0) {
				fprintf (stderr,
					_("%s: failed to add gid range %lu-%lu to '%s'\n"),
					Prog, ptr->range.first, ptr->range.last,
					sub_gid_dbname ());
				fail_exit (E_SUB_GID_UPDATE);
			}
		}
	}
#endif				/* ENABLE_SUBIDS */
	close_files ();

#ifdef WITH_TCB
	if (   (lflg || uflg)
	    && (shadowtcb_move (user_newname, user_newid) == SHADOWTCB_FAILURE) ) {
		exit (E_PW_UPDATE);
	}
#endif

	nscd_flush_cache ("passwd");
	nscd_flush_cache ("group");
	sssd_flush_cache (SSSD_DB_PASSWD | SSSD_DB_GROUP);

#ifdef WITH_SELINUX
	if (Zflg) {
		if ('\0' != *user_selinux) {
			if (set_seuser (user_name, user_selinux) != 0) {
				fprintf (stderr,
				         _("%s: warning: the user name %s to %s SELinux user mapping failed.\n"),
				         Prog, user_name, user_selinux);
#ifdef WITH_AUDIT
				audit_logger (AUDIT_USER_CHAUTHTOK, Prog,
				              "modifying User mapping ",
				              user_name, (unsigned int) user_id,
				              SHADOW_AUDIT_FAILURE);
#endif				/* WITH_AUDIT */
				fail_exit (E_SE_UPDATE);
			}
		} else {
			if (del_seuser (user_name) != 0) {
				fprintf (stderr,
				         _("%s: warning: the user name %s to SELinux user mapping removal failed.\n"),
				         Prog, user_name);
#ifdef WITH_AUDIT
				audit_logger (AUDIT_ADD_USER, Prog,
				              "removing SELinux user mapping",
				              user_name, (unsigned int) user_id,
				              SHADOW_AUDIT_FAILURE);
#endif				/* WITH_AUDIT */
				fail_exit (E_SE_UPDATE);
			}
		}
	}
#endif				/* WITH_SELINUX */

	if (mflg) {
		move_home ();
	}

#ifndef NO_MOVE_MAILBOX
	if (lflg || uflg) {
		move_mailbox ();
	}
#endif				/* NO_MOVE_MAILBOX */

	if (uflg) {
		update_lastlog ();
		update_faillog ();
	}

	if (!mflg && (uflg || gflg)) {
		struct stat sb;

		if (stat (dflg ? prefix_user_newhome : prefix_user_home, &sb) == 0 &&
			((uflg && sb.st_uid == user_newid) || sb.st_uid == user_id)) {
			/*
			 * Change the UID on all of the files owned by
			 * `user_id' to `user_newid' in the user's home
			 * directory.
			 *
			 * move_home() already takes care of changing the
			 * ownership.
			 *
			 */
#ifdef WITH_AUDIT
			if (uflg || gflg) {
				audit_logger (AUDIT_USER_CHAUTHTOK, Prog,
					      "changing home directory owner",
					      user_newname, (unsigned int) user_newid, 1);
			}
#endif
			if (chown_tree (dflg ? prefix_user_newhome : prefix_user_home,
			                user_id,
			                uflg ? user_newid  : (uid_t)-1,
			                user_gid,
			                gflg ? user_newgid : (gid_t)-1) != 0) {
				fprintf (stderr,
				         _("%s: Failed to change ownership of the home directory"),
				         Prog);
				fail_exit (E_HOMEDIR);
			}
		}
	}

	return E_SUCCESS;
}

