static char *
scan_request(char *c)
{
	/* BSD Mandoc stuff */
	static int mandoc_synopsis = 0;	/* True if we are in the synopsis
					 * section */
	static int mandoc_command = 0;	/* True if this is mandoc page */
	static int mandoc_bd_options;	/* Only copes with non-nested Bd's */

	int     i, j, mode = 0;
	char   *h;
	char   *wordlist[MAX_WORDLIST];
	int     words;
	char   *sl;
	STRDEF *owndef;

	while (*c == ' ' || *c == '\t')
		c++;
	if (c[0] == '\n')
		return c + 1;
	if (c[1] == '\n')
		j = 1;
	else
		j = 2;
	while (c[j] == ' ' || c[j] == '\t')
		j++;
	if (c[0] == escapesym) {
		/* some pages use .\" .\$1 .\} */
		/* .\$1 is too difficult/stupid */
		if (c[1] == '$')
			c = skip_till_newline(c);
		else
			c = scan_escape(c + 1);
	} else {
		i = V(c[0], c[1]);
		switch (i) {
		case V('a', 'b'):
			h = c + j;
			while (*h && *h != '\n')
				h++;
			*h = '\0';
			if (scaninbuff && buffpos) {
				buffer[buffpos] = '\0';
				puts(buffer);
			}
			/* fprintf(stderr, "%s\n", c+2); */
			exit(0);
			break;
		case V('d', 'i'):
			{
				STRDEF *de;
				int     oldcurpos = curpos;

				c = c + j;
				i = V(c[0], c[1]);
				if (*c == '\n') {
					c++;
					break;
				}
				while (*c && *c != '\n')
					c++;
				c++;
				h = c;
				while (*c && strncmp(c, ".di", 3))
					while (*c && *c++ != '\n');
				*c = '\0';
				de = strdef;
				while (de && de->nr != i)
					de = de->next;
				if (!de) {
					de = (STRDEF *) xmalloc(sizeof(STRDEF));
					de->nr = i;
					de->slen = 0;
					de->next = strdef;
					de->st = NULL;
					strdef = de;
				} else {
					if (de->st)
						free(de->st);
					de->slen = 0;
					de->st = NULL;
				}
				scan_troff(h, 0, &de->st);
				*c = '.';
				while (*c && *c++ != '\n');
				break;
			}
		case V('d', 's'):
			mode = 1;
		case V('a', 's'):
			{
				STRDEF *de;
				int     oldcurpos = curpos;

				c = c + j;
				i = V(c[0], c[1]);
				j = 0;
				while (c[j] && c[j] != '\n')
					j++;
				if (j < 3) {
					c = c + j;
					break;
				}
				if (c[1] == ' ')
					c = c + 1;
				else
					c = c + 2;
				while (isspace(*c))
					c++;
				if (*c == '"')
					c++;
				de = strdef;
				while (de && de->nr != i)
					de = de->next;
				single_escape = 1;
				curpos = 0;
				if (!de) {
					char   *h;

					de = (STRDEF *) xmalloc(sizeof(STRDEF));
					de->nr = i;
					de->slen = 0;
					de->next = strdef;
					de->st = NULL;
					strdef = de;
					h = NULL;
					c = scan_troff(c, 1, &h);
					de->st = h;
					de->slen = curpos;
				} else {
					if (mode) {
						char   *h = NULL;

						c = scan_troff(c, 1, &h);
						free(de->st);
						de->slen = 0;
						de->st = h;
					} else
						c = scan_troff(c, 1, &de->st);
					de->slen += curpos;
				}
				single_escape = 0;
				curpos = oldcurpos;
			}
			break;
		case V('b', 'r'):
			if (still_dd)
				out_html("<DD>");
			else
				out_html("<BR>\n");
			curpos = 0;
			c = c + j;
			if (c[0] == escapesym) {
				c = scan_escape(c + 1);
			}
			c = skip_till_newline(c);
			break;
		case V('c', '2'):
			c = c + j;
			if (*c != '\n') {
				nobreaksym = *c;
			} else
				nobreaksym = '\'';
			c = skip_till_newline(c);
			break;
		case V('c', 'c'):
			c = c + j;
			if (*c != '\n') {
				controlsym = *c;
			} else
				controlsym = '.';
			c = skip_till_newline(c);
			break;
		case V('c', 'e'):
			c = c + j;
			if (*c == '\n') {
				i = 1;
			} else {
				i = 0;
				while ('0' <= *c && *c <= '9') {
					i = i * 10 + *c - '0';
					c++;
				}
			}
			c = skip_till_newline(c);
			/* center next i lines */
			if (i > 0) {
				out_html("<CENTER>\n");
				while (i && *c) {
					char   *line = NULL;

					c = scan_troff(c, 1, &line);
					if (line && strncmp(line, "<BR>", 4)) {
						out_html(line);
						out_html("<BR>\n");
						i--;
					}
				}
				out_html("</CENTER>\n");
				curpos = 0;
			}
			break;
		case V('e', 'c'):
			c = c + j;
			if (*c != '\n') {
				escapesym = *c;
			} else
				escapesym = '\\';
			break;
			c = skip_till_newline(c);
		case V('e', 'o'):
			escapesym = '\0';
			c = skip_till_newline(c);
			break;
		case V('e', 'x'):
			exit(0);
			break;
		case V('f', 'c'):
			c = c + j;
			if (*c == '\n') {
				fieldsym = padsym = '\0';
			} else {
				fieldsym = c[0];
				padsym = c[1];
			}
