	if (nr == current_size)
		return "";
	i = current_font;
	sizebuf[0] = '\0';
	strcat(sizebuf, change_to_font(0));
	if (current_size)
		strcat(sizebuf, "</FONT>");
	current_size = nr;
	if (nr) {
		int     l;

		strcat(sizebuf, "<FONT SIZE=");
		l = strlen(sizebuf);
