   OLD_USER/OLD_GROUP describe the previous describe_change; USER/GROUP the requested
   new describe_change (a NULL component means that aspect was not being changed). */
void
describe_change (char const *file, enum Change_status changed,
          char const *old_user, char const *old_group,
          char const *user, char const *group)
{
  char *spec;
  char *old_spec;
  char const *fmt;

  if (changed == CH_NOT_APPLIED)
    {
      printf (_("neither symbolic link %s nor referent has been changed\n"),
              quoteaf (file));
