extern int nfds;

int
cron_pclose (FILE *stream)
{
  int fd;
  int status;
  pid_t pid;
  sigset_t nmask, omask;

  fd = fileno (stream);
  if (pids == NULL || fd >= nfds || pids[fd] == 0)
    return -1;

  fclose (stream);

  sigemptyset (&nmask);
  sigaddset (&nmask, SIGINT);
  sigaddset (&nmask, SIGQUIT);
  sigaddset (&nmask, SIGHUP);
  sigprocmask (SIG_BLOCK, &nmask, &omask);

  do
    pid = wait (&status);
