				unget_char(ch, file);
				if (get_number(&num3, 0, PPC_NULL, file) != EOF
				    && num3 != 0) {
					state = R_TERMS;
					break;
				}
				return (EOF);

			case R_TERMS:
				if (is_separator(ch)) {
					state = R_FINISH;
					break;
				}
				return (EOF);

			case R_NUM1:
				if (ch == '-') {
					state = R_RANGE;
					break;
				}
				if (ch == '~') {
					state = R_RANDOM;
					break;
				}
				if (is_separator(ch)) {
					num2 = num1;
					state = R_FINISH;
					break;
				}
				return (EOF);

			case R_RANGE:
				unget_char(ch, file);
				if (get_number(&num2, low, names, file) != EOF) {
					state = R_RANGE_NUM2;
					break;
				}
				return (EOF);

			case R_RANGE_NUM2:
				if (ch == '/') {
					state = R_STEP;
					break;
				}
				if (is_separator(ch)) {
					state = R_FINISH;
					break;
				}
				return (EOF);

			case R_RANDOM:
				if (is_separator(ch)) {
					num2 = high;
					state = R_FINISH;
				}
				else if (unget_char(ch, file),
