static int
get_range(bitstr_t * bits, int low, int high, const char *names[],
		FILE * file) {
	/* range = number | number "-" number [ "/" number ]
	 *         | [number] "~" [number]
	 */

	int ch, i, num1, num2, num3;

	/* default value for step
	 */
	num3 = 1;
	range_state_t state = R_START;

	while (state != R_FINISH && ((ch = get_char(file)) != EOF)) {
		switch (state) {
			case R_START:
				if (ch == '*') {
					num1 = low;
					num2 = high;
					state = R_AST;
					break;
				}
				if (ch == '~') {
					num1 = low;
					state = R_RANDOM;
					break;
				}
				unget_char(ch, file);
				if (get_number(&num1, low, names, file) != EOF) {
					state = R_NUM1;
					break;
				}
				return (EOF);

			case R_AST:
				if (ch == '/') {
					state = R_STEP;
					break;
				}
				if (is_separator(ch)) {
					state = R_FINISH;
					break;
				}
				return (EOF);

			case R_STEP:
				unget_char(ch, file);
				if (get_number(&num3, 0, PPC_NULL, file) != EOF
				    && num3 != 0) {
					state = R_TERMS;
					break;
				}
				return (EOF);

			case R_TERMS:
				if (is_separator(ch)) {
					state = R_FINISH;
					break;
				}
				return (EOF);

			case R_NUM1:
				if (ch == '-') {
					state = R_RANGE;
					break;
				}
				if (ch == '~') {
					state = R_RANDOM;
					break;
				}
				if (is_separator(ch)) {
					num2 = num1;
					state = R_FINISH;
					break;
				}
				return (EOF);

			case R_RANGE:
				unget_char(ch, file);
				if (get_number(&num2, low, names, file) != EOF) {
					state = R_RANGE_NUM2;
					break;
				}
				return (EOF);

			case R_RANGE_NUM2:
				if (ch == '/') {
					state = R_STEP;
					break;
				}
				if (is_separator(ch)) {
					state = R_FINISH;
					break;
				}
				return (EOF);

			case R_RANDOM:
				if (is_separator(ch)) {
					num2 = high;
					state = R_FINISH;
				}
				else if (unget_char(ch, file),
						get_number(&num2, low, names, file) != EOF) {
					state = R_TERMS;
				}
				/* fail if couldn't find match on previous term
				 */
				else
					return (EOF);

				/* if invalid random range was selected */
				if (num1 > num2)
					return (EOF);

				/* select random number in range <num1, num2>
				 */
				num1 = num2 = random() % (num2 - num1 + 1) + num1;
				break;


			default:
				/* We should never get here
				 */
				return (EOF);
		}
	}
	if (state != R_FINISH || ch == EOF)
		return (EOF);

	for (i = num1; i <= num2; i += num3)
		if (EOF == set_element(bits, low, high, i)) {
			unget_char(ch, file);
			return (EOF);
		}
	return ch;
}

