              break;
            }

          undotlines (outputfile, dotlines (outputfile, b, mapping[FILE2]),
                      low0, D_NUMLINES (b, mapping[FILE2]));
        }
    }
  if (finalwrite)
    fputs ("w\nq\n", outputfile);
  return conflicts_found;
}

