#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <wchar.h>

typedef ptrdiff_t idx_t;

struct localeinfo {
    bool multibyte;
    bool simple;
    bool using_utf8;
    signed char sbclen[UCHAR_MAX + 1];
    wint_t sbctowc[UCHAR_MAX + 1];
};

typedef idx_t (*execute_fn)(void *, const char *, idx_t, idx_t *, const char *);

struct matcher {
    char name[12];
    int syntax;
    void *(*compile)(char *, idx_t, unsigned long, bool);
    execute_fn execute;
};

struct color_cap {
    const char *name;
    const char **var;
    void (*fct)(void);
};

struct hash_table;
struct hash_tuning;
struct exclude;

enum {
    BINARY_FILES_OPTION = 128,
    COLOR_OPTION,
    EXCLUDE_DIRECTORY_OPTION,
    EXCLUDE_OPTION,
    EXCLUDE_FROM_OPTION,
    GROUP_SEPARATOR_OPTION,
    INCLUDE_OPTION,
    LINE_BUFFERED_OPTION,
    LABEL_OPTION,
    NO_IGNORE_CASE_OPTION
};

enum { GREP_MATCHER, EGREP_MATCHER, FGREP_MATCHER };
enum { READ_DIRECTORIES = 2, RECURSE_DIRECTORIES, SKIP_DIRECTORIES };
enum { READ_DEVICES = 1, SKIP_DEVICES };
enum { BINARY_BINARY, BINARY_TEXT, BINARY_WITHOUT_MATCH };
enum { LIST_NONE, LIST_MATCHING, LIST_NONMATCHING };
enum {
    EXCLUDE_WILDCARDS = 0x10000000,
    EXCLUDE_INCLUDE = 0x20000000,
    EXCLUDE_ANCHORED = 0x40000000
};

extern struct localeinfo localeinfo;
extern const struct option long_options[];
extern const struct matcher matchers[];
extern const struct color_cap color_dict[];
extern const char *const directories_args[];
extern const int directories_types[];
extern void (*argmatch_die)(void);
extern struct hash_table *pattern_table;
extern struct exclude *excluded_patterns[2];
extern struct exclude *excluded_directory_patterns[2];
extern char *pattern_keys;
extern idx_t num_patterns;
extern signed char sb_icase[UCHAR_MAX + 1];
extern char eolbyte;
extern bool match_icase, match_words, match_lines;
extern bool out_byte, out_line, out_invert, out_quiet, out_tab;
extern bool count_matches, only_matching, line_buffered;
extern bool exit_on_match, stdout_null, done_on_match, skip_empty_lines;
extern bool suppress_errors, show_version, errseen, omit_dot_slash;
extern int show_help, color_option, binary_files, directories, devices;
extern int list_files, out_file, filename_mask, fts_options, exit_failure;
extern intmax_t max_count, out_before, out_after;
extern const char *label, *filename, *group_separator;
extern const char *selected_match_color, *context_match_color;
extern uintmax_t mb_mask;
extern size_t pagesize, bufalloc;
extern char *buffer;
extern struct stat out_stat;
extern void *compiled_pattern;
extern execute_fn execute;

extern void init_localeinfo(struct localeinfo *);
extern void clean_up_stdout(void);
extern int c_stack_action(void (*)(int));
extern struct hash_table *hash_initialize(size_t, const struct hash_tuning *,
                                         size_t (*)(const void *, size_t),
                                         bool (*)(const void *, const void *),
                                         void (*)(void *));
extern size_t hash_pattern(const void *, size_t);
extern bool compare_patterns(const void *, const void *);
extern void hash_free(struct hash_table *);
extern _Noreturn void xalloc_die(void);
extern void *xmalloc(size_t);
extern char *xstrdup(const char *);
extern void *xpalloc(void *, idx_t *, idx_t, idx_t, idx_t);
extern int setmatcher(const char *, int);
extern void context_length_arg(const char *, intmax_t *);
extern int xstrtoimax(const char *, char **, int, intmax_t *, const char *);
extern idx_t update_keys(char *, idx_t, idx_t, const char *);
extern void wordinit(void);
extern int c_strcasecmp(const char *, const char *);
extern ptrdiff_t __xargmatch_internal(const char *, const char *,
                                    const char *const *, const void *, size_t,
                                    void (*)(void), bool);
extern struct exclude *new_exclude(void);
extern void add_exclude(struct exclude *, const char *, int);
extern int add_exclude_file(void (*)(struct exclude *, const char *, int),
                            struct exclude *, const char *, int, char);
extern bool strip_trailing_slashes(char *);
extern _Noreturn void usage(int);
extern const char *getprogname(void);
extern void version_etc(FILE *, const char *, const char *, const char *, ...);
extern int should_colorize(void);
extern void init_colorize(void);
extern int case_folded_counterparts(wint_t, wchar_t *);
extern size_t rpl_mbrlen(const char *, size_t, mbstate_t *);
extern idx_t mb_clen(const char *, idx_t, mbstate_t *);
extern idx_t mb_icase(const char *, idx_t, mbstate_t *);
extern void fgrep_to_grep(char **, idx_t *);
extern bool grepdesc(int, bool);
extern bool grepfile(int, const char *, bool, bool);

int main(int argc, char **argv)
{
    char *keys = NULL;
    idx_t keycc = 0;
    idx_t keyalloc = 0;
    intmax_t default_context = -1;
    int matcher = -1;
    int last_recursive = 0;
    int with_filenames = 0;
    static int last_digit_optind = -1;
    char contextbuf[25];

    eolbyte = '\n';
    exit_failure = 2;
    filename_mask = -1;
    max_count = INTMAX_MAX;
    out_before = out_after = -1;
    only_matching = false;

    setlocale(LC_ALL, "");
    bindtextdomain("grep", "/usr/local/share/locale");
    textdomain("grep");
    init_localeinfo(&localeinfo);
    atexit(clean_up_stdout);
    c_stack_action(NULL);
    pattern_table = hash_initialize(0, NULL, hash_pattern, compare_patterns, NULL);
    if (!pattern_table)
        xalloc_die();

    for (;;) {
        int option_index = optind;
        int previous_optind = optind;
        char *context_end = contextbuf;
        bool have_digit = false;
        int opt;

        for (;;) {
            opt = getopt_long(argc, argv,
                              "0123456789A:B:C:D:EFGHIPTUVX:abcd:e:f:hiLlm:noqRrsuvwxyZz",
                              long_options, NULL);
            if (opt < '0' || opt > '9')
                break;

            char *p = contextbuf;
            if (have_digit && last_digit_optind == previous_optind) {
                p = context_end - (contextbuf[0] == '0');
                if (p == contextbuf + 21) {
                    memcpy(p, "...", 4);
                    context_end = p + 3;
                    break;
                }
            }
            last_digit_optind = previous_optind;
            *p++ = (char)opt;
            context_end = p;
            previous_optind = optind;
            have_digit = true;
        }

        if (context_end != contextbuf) {
            *context_end = '\0';
            context_length_arg(contextbuf, &default_context);
        }
        if (opt == -1)
            break;

        switch (opt) {
        case 0:
        case 'U':
            break;
        case 'A':
            context_length_arg(optarg, &out_after);
            break;
        case 'B':
            context_length_arg(optarg, &out_before);
            break;
        case 'C':
            context_length_arg(optarg, &default_context);
            break;
        case 'D':
            if (strcmp(optarg, "read") == 0)
                devices = READ_DEVICES;
            else if (strcmp(optarg, "skip") == 0)
                devices = SKIP_DEVICES;
            else
                error(2, 0, dcgettext(NULL, "unknown devices method", LC_MESSAGES));
            break;
        case 'E':
            matcher = setmatcher("egrep", matcher);
            break;
        case 'F':
            matcher = setmatcher("fgrep", matcher);
            break;
        case 'G':
            matcher = setmatcher("grep", matcher);
            break;
        case 'H':
            with_filenames = 1;
            break;
        case 'I':
            binary_files = BINARY_WITHOUT_MATCH;
            break;
        case 'L':
            list_files = LIST_NONMATCHING;
            break;
        case 'P':
            matcher = setmatcher("perl", matcher);
            break;
        case 'R':
        case 'r':
            if (opt == 'R')
                fts_options = 0x30a;
            directories = RECURSE_DIRECTORIES;
            last_recursive = option_index;
            break;
        case 'T':
            out_tab = true;
            break;
        case 'V':
            show_version = true;
            break;
        case 'X':
            matcher = setmatcher(optarg, matcher);
            break;
        case 'Z':
            filename_mask = 0;
            break;
        case 'a':
            binary_files = BINARY_TEXT;
            break;
        case 'b':
            out_byte = true;
            break;
        case 'c':
            count_matches = true;
            break;
        case 'd': {
            ptrdiff_t index = __xargmatch_internal("--directories", optarg,
                                                  directories_args, directories_types,
                                                  sizeof directories_types[0],
                                                  argmatch_die, true);
            directories = directories_types[index];
            if (directories == RECURSE_DIRECTORIES)
                last_recursive = option_index;
            break;
        }
        case 'e': {
            idx_t len = strlen(optarg);
            idx_t needed = keycc - keyalloc + len + 1;
            if (needed > 0)
                pattern_keys = keys = xpalloc(keys, &keyalloc, needed, -1, 1);
            char *end = mempcpy(keys + keycc, optarg, len);
            *end = '\n';
            keycc = update_keys(keys, keycc, keycc + len + 1, "");
            break;
        }
        case 'f': {
            FILE *fp = strcmp(optarg, "-") == 0 ? stdin : fopen(optarg, "r");
            if (!fp)
                error(2, errno, "%s", optarg);

            idx_t oldcc = keycc;
            idx_t newcc = keycc;
            for (;;) {
                idx_t needed = newcc - keyalloc + 2;
                if (needed > 0)
                    pattern_keys = keys = xpalloc(keys, &keyalloc, needed, -1, 1);
                size_t nread = fread_unlocked(keys + newcc, 1,
                                             keyalloc - newcc - 1, fp);
                if (nread == 0)
                    break;
                newcc += nread;
            }

            int saved_errno = errno;
            bool failed = ferror_unlocked(fp) != 0;
            if (!failed) {
                if (fp == stdin)
                    clearerr_unlocked(fp);
                else if (fclose(fp) != 0) {
                    failed = true;
                    saved_errno = errno;
                }
            }
            if (failed && saved_errno)
                error(2, saved_errno, "%s", optarg);

            if (newcc != oldcc && keys[newcc - 1] != '\n')
                keys[newcc++] = '\n';
            keycc = update_keys(keys, oldcc, newcc, optarg);
            break;
        }
        case 'h':
            with_filenames = -1;
            break;
        case 'i':
        case 'y':
            match_icase = true;
            break;
        case 'l':
            list_files = LIST_MATCHING;
            break;
        case 'm':
            if (xstrtoimax(optarg, NULL, 10, &max_count, "") > 1)
                error(2, 0, dcgettext(NULL, "invalid max count", LC_MESSAGES));
            break;
        case 'n':
            out_line = true;
            break;
        case 'o':
            only_matching = true;
            break;
        case 'q':
            exit_on_match = true;
            exit_failure = 0;
            break;
        case 's':
            suppress_errors = true;
            break;
        case 'u':
            error(0, 0, dcgettext(NULL,
                                 "warning: --unix-byte-offsets (-u) is obsolete",
                                 LC_MESSAGES));
            break;
        case 'v':
            out_invert = true;
            break;
        case 'w':
            wordinit();
            match_words = true;
            break;
        case 'x':
            match_lines = true;
            break;
        case 'z':
            eolbyte = '\0';
            break;
        case BINARY_FILES_OPTION:
            if (strcmp(optarg, "binary") == 0)
                binary_files = BINARY_BINARY;
            else if (strcmp(optarg, "text") == 0)
                binary_files = BINARY_TEXT;
            else if (strcmp(optarg, "without-match") == 0)
                binary_files = BINARY_WITHOUT_MATCH;
            else
                error(2, 0, dcgettext(NULL, "unknown binary-files type", LC_MESSAGES));
            break;
        case COLOR_OPTION:
            if (!optarg)
                color_option = 2;
            else if (c_strcasecmp(optarg, "always") == 0
                     || c_strcasecmp(optarg, "yes") == 0
                     || c_strcasecmp(optarg, "force") == 0)
                color_option = 1;
            else if (c_strcasecmp(optarg, "never") == 0
                     || c_strcasecmp(optarg, "no") == 0
                     || c_strcasecmp(optarg, "none") == 0)
                color_option = 0;
            else if (c_strcasecmp(optarg, "auto") == 0
                     || c_strcasecmp(optarg, "tty") == 0
                     || c_strcasecmp(optarg, "if-tty") == 0)
                color_option = 2;
            else
                show_help = 1;
            break;
        case EXCLUDE_DIRECTORY_OPTION:
            strip_trailing_slashes(optarg);
            for (int i = 0; i < 2; i++) {
                if (!excluded_directory_patterns[i])
                    excluded_directory_patterns[i] = new_exclude();
                add_exclude(excluded_directory_patterns[i], optarg,
                            EXCLUDE_WILDCARDS | (i == 0 ? EXCLUDE_ANCHORED : 0));
            }
            break;
        case EXCLUDE_OPTION:
        case INCLUDE_OPTION:
            for (int i = 0; i < 2; i++) {
                if (!excluded_patterns[i])
                    excluded_patterns[i] = new_exclude();
                add_exclude(excluded_patterns[i], optarg,
                            EXCLUDE_WILDCARDS
                            | (i == 0 ? EXCLUDE_ANCHORED : 0)
                            | (opt == INCLUDE_OPTION ? EXCLUDE_INCLUDE : 0));
            }
            break;
        case EXCLUDE_FROM_OPTION:
            for (int i = 0; i < 2; i++) {
                if (!excluded_patterns[i])
                    excluded_patterns[i] = new_exclude();
                if (add_exclude_file(add_exclude, excluded_patterns[i], optarg,
                                     EXCLUDE_WILDCARDS
                                     | (i == 0 ? EXCLUDE_ANCHORED : 0), '\n') != 0)
                    error(2, errno, "%s", optarg);
            }
            break;
        case GROUP_SEPARATOR_OPTION:
            group_separator = optarg;
            break;
        case LINE_BUFFERED_OPTION:
            line_buffered = true;
            break;
        case LABEL_OPTION:
            label = optarg;
            break;
        case NO_IGNORE_CASE_OPTION:
            match_icase = false;
            break;
        default:
            usage(2);
        }
    }

    if (show_version) {
        version_etc(stdout, getprogname(), "GNU grep", "3.8", (char *)NULL);
        puts(dcgettext(NULL,
                       "Written by Mike Haertel and others; see\n"
                       "<https://git.sv.gnu.org/cgit/grep.git/tree/AUTHORS>.\n",
                       LC_MESSAGES));
        return 0;
    }
    if (show_help)
        usage(0);

    if (keys) {
        if (keycc == 0) {
            match_words = match_lines = false;
            out_invert = !out_invert;
            keys[0] = '\n';
            keycc = 1;
        }
    } else {
        if (optind >= argc)
            usage(2);
        const char *pattern = argv[optind++];
        if (matcher != FGREP_MATCHER && pattern[0] == '\\' && pattern[1] == '-')
            pattern++;
        pattern_keys = keys = xstrdup(pattern);
        idx_t len = strlen(keys);
        keys[len] = '\n';
        keycc = update_keys(keys, 0, len + 1, "");
    }
    keycc--;
    hash_free(pattern_table);

    bool possibly_tty = false;
    if (exit_on_match) {
        list_files = LIST_NONE;
        count_matches = false;
        out_quiet = true;
    } else {
        struct stat st;
        if (fstat(STDOUT_FILENO, &st) == 0) {
            if (S_ISREG(st.st_mode))
                out_stat = st;
            else if (S_ISCHR(st.st_mode)) {
                struct stat null_stat;
                if (stat("/dev/null", &null_stat) == 0
                    && st.st_ino == null_stat.st_ino
                    && st.st_dev == null_stat.st_dev)
                    stdout_null = true;
                else
                    possibly_tty = true;
            }
        }
        if (stdout_null)
            list_files = LIST_NONE;
        if (stdout_null || list_files != LIST_NONE) {
            count_matches = false;
            out_quiet = true;
        }
    }
    done_on_match = count_matches | out_quiet;
    if (out_after < 0)
        out_after = default_context;
    if (out_before < 0)
        out_before = default_context;

    if ((max_count == 0
         || (keycc == 0 && out_invert && !match_lines && !match_words))
        && list_files != LIST_NONMATCHING)
        return 1;

    if (color_option == 2)
        color_option = possibly_tty && should_colorize() && isatty(STDOUT_FILENO);
    init_colorize();

    if (color_option) {
        const char *grep_color = getenv("GREP_COLOR");
        if (grep_color && *grep_color) {
            const char *p = grep_color;
            while (*p == ';' || ('0' <= *p && *p <= '9'))
                p++;
            if (*p == '\0')
                selected_match_color = context_match_color = grep_color;
        }

        const char *grep_colors = getenv("GREP_COLORS");
        if (grep_colors && *grep_colors) {
            char *cap_name = xstrdup(grep_colors);
            char *value = NULL;
            for (char *p = cap_name; ; p++) {
                char c = *p;
                if (c == ':' || c == '\0') {
                    *p = '\0';
                    const struct color_cap *cap = color_dict;
                    while (cap->name && strcmp(cap->name, cap_name) != 0)
                        cap++;
                    if (cap->var && value)
                        *cap->var = value;
                    if (cap->fct)
                        cap->fct();
                    if (c == '\0')
                        break;
                    cap_name = p + 1;
                    value = NULL;
                } else if (c == '=') {
                    if (p == cap_name || value)
                        break;
                    *p = '\0';
                    value = p + 1;
                } else if (value && c != ';' && (c < '0' || c > '9')) {
                    break;
                }
            }
        }

        if (selected_match_color == grep_color || context_match_color == grep_color)
            error(0, 0, dcgettext(NULL,
                                 "warning: GREP_COLOR='%s' is deprecated; use GREP_COLORS='mt=%s'",
                                 LC_MESSAGES), grep_color, grep_color);
    }

    unsigned char mask = 0;
    unsigned int bit = 1;
    for (unsigned int c = 1; c <= UCHAR_MAX; c++) {
        if (localeinfo.sbclen[c] != 1 && !(mask & c)) {
            while (bit * 2 <= c)
                bit *= 2;
            mask |= bit;
        }
    }
    mb_mask = mask * UINT64_C(0x0101010101010101);

    int matcher_index = matcher < 0 ? GREP_MATCHER : matcher;
    if (matcher <= FGREP_MATCHER) {
        if (match_icase) {
            for (unsigned int c = 0; c <= UCHAR_MAX; c++) {
                if (localeinfo.sbctowc[c] != WEOF) {
                    wchar_t folded[32];
                    int n = case_folded_counterparts(localeinfo.sbctowc[c], folded);
                    signed char len = 1;
                    while (n > 0) {
                        mbstate_t state = { 0 };
                        char buf[MB_LEN_MAX];
                        if (wcrtomb(buf, folded[--n], &state) != 1) {
                            len = -1;
                            break;
                        }
                    }
                    sb_icase[c] = len;
                }
            }
        }

        if (matcher == FGREP_MATCHER) {
            bool use_regex = false;
            if (localeinfo.multibyte) {
                mbstate_t state = { 0 };
                for (idx_t i = 0; i < keycc; ) {
                    idx_t len = localeinfo.sbclen[(unsigned char)keys[i]];
                    if (len == -2)
                        len = (idx_t)rpl_mbrlen(keys + i, keycc - i, &state);
                    if (len < 0) {
                        use_regex = true;
                        break;
                    }
                    i += len;
                }
                if (!use_regex && match_icase) {
                    state = (mbstate_t){ 0 };
                    for (idx_t i = 0; i < keycc; ) {
                        unsigned char c = keys[i];
                        idx_t len = localeinfo.sbctowc[c] == WEOF
                                    ? mb_icase(keys + i, keycc - i, &state)
                                    : sb_icase[c];
                        if (len < 0) {
                            use_regex = true;
                            break;
                        }
                        i += len;
                    }
                }
            } else {
                use_regex = num_patterns == 1 && match_words;
            }
            if (use_regex) {
                fgrep_to_grep(&pattern_keys, &keycc);
                keys = pattern_keys;
                matcher_index = GREP_MATCHER;
            }
        } else if (num_patterns > 1) {
            char *literal = xmalloc(keycc + 1);
            char *out = literal;
            const char *p = keys;
            idx_t remaining = keycc;
            mbstate_t state = { 0 };
            bool is_literal = true;

            while (remaining != 0) {
                switch (*p) {
                case '$':
                case '*':
                case '.':
                case '[':
                case '^':
                    is_literal = false;
                    break;
                case '(':
                case ')':
                case '+':
                case '?':
                case '{':
                case '|':
                    if (matcher == EGREP_MATCHER)
                        is_literal = false;
                    break;
                case '\\':
                    if (remaining > 1) {
                        switch (p[1]) {
                        case '\n':
                        case '\'':
                        case '1':
                        case '2':
                        case '3':
                        case '4':
                        case '5':
                        case '6':
                        case '7':
                        case '8':
                        case '9':
                        case '<':
                        case '>':
                        case 'B':
                        case 'S':
                        case 'W':
                        case '`':
                        case 'b':
                        case 's':
                        case 'w':
                            is_literal = false;
                            break;
                        case '(':
                        case ')':
                        case '+':
                        case '?':
                        case '{':
                        case '|':
                            if (matcher != EGREP_MATCHER) {
                                matcher_index = GREP_MATCHER;
                                is_literal = false;
                            }
                            break;
                        }
                        if (is_literal) {
                            p++;
                            remaining--;
                        }
                    }
                    break;
                }
                if (!is_literal)
                    break;

                idx_t len;
                if (match_icase) {
                    unsigned char c = *p;
                    len = localeinfo.sbctowc[c] == WEOF
                          ? mb_icase(p, remaining, &state) : sb_icase[c];
                } else {
                    len = mb_clen(p, remaining, &state);
                }
                if (len < 0) {
                    is_literal = false;
                    break;
                }
                out = mempcpy(out, p, len);
                p += len;
                remaining -= len;
            }

            if (is_literal) {
                matcher_index = FGREP_MATCHER;
                idx_t len = out - literal;
                if (len != keycc) {
                    keycc = len;
                    char *end = mempcpy(keys, literal, len);
                    *end = '\n';
                }
            }
            free(literal);
        }
    }

    const struct matcher *m = &matchers[matcher_index];
    execute = m->execute;
    compiled_pattern = m->compile(keys, keycc, m->syntax,
                                  only_matching || color_option);
    char empty_line[3] = { '\0', eolbyte, '\0' };
    idx_t match_size;
    skip_empty_lines = (execute(compiled_pattern, empty_line + 1, 1,
                                &match_size, NULL) == 0) == out_invert;

    int nfiles = argc - optind;
    if (with_filenames != 0 || nfiles > 1)
        out_file = with_filenames >= 0;
    else
        out_file = directories == RECURSE_DIRECTORIES ? -1 : 0;

    size_t page_size = sysconf(_SC_PAGESIZE);
    if (page_size == 0 || page_size > (PTRDIFF_MAX - sizeof(uintmax_t)) / 2)
        abort();
    pagesize = page_size;
    size_t initial_size = 96 * 1024;
    size_t remainder = initial_size % pagesize;
    if (remainder != 0)
