    uint32_t CFSR;           /* 0x28 Configurable Fault Status  */
    uint32_t HFSR;           /* 0x2C HardFault Status           */
    uint32_t DFSR;           /* 0x30 Debug Fault Status         */
    uint32_t MMFAR;          /* 0x34 MemManage Fault Address    */
    uint32_t BFAR;           /* 0x38 BusFault Address           */
    uint32_t AFSR;           /* 0x3C Auxiliary Fault Status     */
} scb_fault_t;

